   "hi": "$A$ के सदस्य हैं 1, 2 और समुच्चय $\\{3\\}$। अकेली संख्या 3 सदस्य **नहीं** है — $\\{3\\} \\in A$ सही है, पर $3 \\in A$ ग़लत। पूरा फ़र्क़ मझले कोष्ठक का है, और यह भेद कक्षा 11 भर चुपचाप नंबर काटता रहता है।"
