   "hi": "पूर्ण संख्याएँ हैं $0, 1, 2, 3, \\ldots$ और पूर्णांक हैं $\\ldots -2, -1, 0, 1, 2 \\ldots$। हर पूर्ण संख्या उस लंबी सूची में है। पूर्णांक बस ऋणात्मक हिस्सा और जोड़ देते हैं।"
