  "q": {
   "en": "Write $\\{x : x \\in \\mathbb{N}, x \\leq 4\\}$ as a list.",
   "hi": "$\\{x : x \\in \\mathbb{N}, x \\leq 4\\}$ को सूची के रूप में लिखिए।"
  },
