   "hi": "*ऊँचा* की कोई तय ऊँचाई नहीं है। कोई 4 मीटर के पेड़ को गिनेगा, कोई नहीं। एक संख्या जोड़ दीजिए — *5 मीटर से ऊँचे पेड़* — और यह तुरंत सही समुच्चय बन जाता है।"
